def is_valid(pos, num, seq):
    n = len(seq)
    if pos + num + 1 >= n or seq[pos + num + 1] != 0:
        return False
    return True

def solve_langford(seq, used, pos=0):
    if pos == len(seq):
        return all(used[i] for i in range(1,9))

    if seq[pos] != 0:
        return solve_langford(seq, used, pos+1)

    for num in range(8,0,-1):
        if used[num] or not is_valid(pos, num, seq):
            continue
        # place
        seq[pos] = num
        seq[pos + num + 1] = num
        used[num] = True

        if solve_langford(seq, used, pos+1):
            return True

        # backtrack
        seq[pos] = 0
        seq[pos + num + 1] = 0
        used[num] = False
    return False

# Partial assignment, 0-based
partial = {4:7, 8:5, 10:4}
seq = [0]*16
used = [False]*9  # 1 to 8

consistent = True
for p, v in partial.items():
    if seq[p] != 0 and seq[p] != v:
        consistent = False
        break
    if seq[p] == 0:
        other = p + v + 1
        if other >= 16 or seq[other] != 0 and seq[other] != v:
            consistent = False
            break
        seq[p] = v
        seq[other] = v
        if used[v]:
            consistent = False
            break
        used[v] = True

print("Consistent partial:", consistent)
if consistent:
    if solve_langford(seq, used):
        print(seq)
    else:
        print("No solution found")
else:
    print("UNSATISFIABLE")
